window.SortafunFreq = (function () {
  var map = null;
  function build() {
    if (map) return;
    map = {};
    var c = window.SortafunDict.common, r = window.SORTAFUN_FREQ_RAW;
    if (c.length !== r.length) return; // dict.js changed without a rebuild: everything reads 0
    for (var i = 0; i < c.length; i++) map[c[i]] = (r.charCodeAt(i) - 35 + 29) / 10;
  }
  return { zipf: function (w) { build(); return map[String(w).toLowerCase()] || 0; } };
})();
